// DetectRoot walks upward to the nearest pom.xml. It performs no writes.
func DetectRoot(start string) (string, error) {
	absolute, err := filepath.Abs(start)
	if err != nil {
		return "", err
	}
	for {
		if info, e := os.Stat(filepath.Join(absolute, "pom.xml")); e == nil && !info.IsDir() {
			return absolute, nil
		}
		parent := filepath.Dir(absolute)
		if parent == absolute {
			return "", fmt.Errorf("project.root: no pom.xml found from %s", start)
		}
		absolute = parent
	}
}
